public class Main {
    static int[] a = {1, 2, 3, 4, 5};

    static int count(int i, int rem) {
        if (rem == 0) return 1;
        if (rem < 0 || i == a.length) return 0;
        return count(i + 1, rem - a[i]) + count(i + 1, rem);
    }

    public static void main(String[] args) {
        System.out.println(count(0, 5));
    }
}

